// Play Console measures the *DEX*, not the JS bundle: a release build with
// `minifyEnabled false` keeps every class name it ships, which is exactly what
// the 1.1.0 upload reported as "Obfuscation 1 %" ("DEX code optimization is
// below our threshold"). The switch lives in `app.config.js` (through
// `expo-build-properties`) because `android/` is generated by prebuild, so a
// hand edit there would be gone on the next `expo prebuild --clean` - and the
// regression would only surface again in the Play Console, weeks later.
//
// This reads the config as text on purpose: importing it would execute a
// prebuild-time module (it reads `app-links.json` and the environment), and the
// guard only needs the two keys that make R8 run.
import { readFileSync } from "node:fs"
import path from "node:path"
import { describe, expect, it } from "vitest"

const root = path.resolve(__dirname, "../..")
const config = readFileSync(path.join(root, "app.config.js"), "utf8")

/** The `android` block of the expo-build-properties plugin config. */
const androidBlock = config.slice(
  config.indexOf("android: {", config.indexOf("expo-build-properties")),
)

describe("release build optimisation (Play: DEX obfuscation)", () => {
  it("enables R8 in release builds", () => {
    expect(androidBlock).toMatch(/enableMinifyInReleaseBuilds:\s*true/)
  })

  it("keeps the line numbers a release stack trace needs", () => {
    expect(config).toMatch(/extraProguardRules:\s*androidProguardRules/)
    expect(config).toMatch(/-keepattributes SourceFile,LineNumberTable/)
  })

  it("does not ask for resource shrinking, which needs its own keep pass", () => {
    expect(androidBlock).not.toMatch(/enableShrinkResourcesInReleaseBuilds:\s*true/)
  })

  it("gives the Gradle daemon the heap R8 needs", () => {
    expect(config).toContain("./plugins/withAndroidMemory")
    const plugin = readFileSync(
      path.join(root, "plugins/withAndroidMemory.js"),
      "utf8",
    )
    expect(plugin).toMatch(/org\.gradle\.jvmargs/)
    // The template's 2 GB is what OOMs; anything at 4 GB or more is the fix.
    const heap = /const DEFAULT_ARGS = "-Xmx(\d+)m/.exec(plugin)
    expect(heap).not.toBeNull()
    expect(Number(heap?.[1])).toBeGreaterThanOrEqual(4096)
  })
})
